import { execSync, type ExecSyncOptions } from 'node:child_process'

export interface ShellResult {
  stdout: string
  success: boolean
  exitCode: number
}

export function shell(command: string, options?: ExecSyncOptions): ShellResult {
  try {
    const stdout = execSync(command, {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
      timeout: 120_000,
      ...options,
    })
    return { stdout: String(stdout).trim(), success: true, exitCode: 0 }
  } catch (error: unknown) {
    const execError = error as { status?: number; stdout?: string | Buffer }
    return {
      stdout: String(execError.stdout ?? '').trim(),
      success: false,
      exitCode: execError.status ?? 1,
    }
  }
}

export function shellOrThrow(command: string, options?: ExecSyncOptions): string {
  const result = shell(command, options)
  if (!result.success) {
    throw new Error(`Command failed (exit ${result.exitCode}): ${command}\n${result.stdout}`)
  }
  return result.stdout
}
